import sys

def solve() -> None:
    n = int(sys.stdin.readline())
    result = [0] * (2 * n)

    for i in range(1, n + 1):
        if i % 2 == 1:
            # Odd number, place in first half
            pos = (i - 1) // 2
        else:
            # Even number, place in second half
            pos = n + (i // 2 - 1)

        result[pos] = i

    sys.stdout.write(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
