import sys

def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    tiles = list(map(int, data[1:1+n]))

    # Count occurrences of 1 and 2
    count_1 = tiles.count(1)
    count_2 = tiles.count(2)

    # Start with 2 if possible
    result = []
    if count_2 > 0:
        result.append(2)
        count_2 -= 1

    # Add 1 if we have any
    if count_1 > 0:
        result.append(1)
        count_1 -= 1

    # Add all remaining 2s
    while count_2 > 0:
        result.append(2)
        count_2 -= 1

    # Add all remaining 1s
    while count_1 > 0:
        result.append(1)
        count_1 -= 1

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

