def solve():
    n, m, k = map(int, input().split())

    # grid to store the current state of cells
    grid = [[-1 for _ in range(m)] for _ in range(n)]

    # count empty cells in first row and first column
    empty_first_row = n
    empty_first_col = m

    for _ in range(k):
        x, y, t = map(int, input().split())
        x -= 1  # 0-indexed
        y -= 1

        if t == -1:
            # clear the cell
            if grid[x][y] != -1:
                grid[x][y] = -1
                if x == 0:
                    empty_first_row += 1
                if y == 0:
                    empty_first_col += 1
        elif t == 0:
            # write 0
            if grid[x][y] == -1:
                grid[x][y] = 0
                if x == 0:
                    empty_first_row -= 1
                if y == 0:
                    empty_first_col -= 1
        elif t == 1:
            # write 1
            if grid[x][y] == -1:
                grid[x][y] = 1
                if x == 0:
                    empty_first_row -= 1
                if y == 0:
                    empty_first_col -= 1

        # Check if constraints are consistent
        consistent = True

        # If we have at least one cell in first row and first column set,
        # we can try to fill the matrix and check consistency
        if empty_first_row == 0 and empty_first_col == 0:
            # All first row and column are set
            # Check if the matrix is beautiful
            consistent = True

            # Fill the matrix based on first row and column
            for i in range(1, n):
                for j in range(1, m):
                    # (i, j) is determined by (i-1, j) and (i, j-1)
                    val = (grid[i-1][j] + grid[i][j-1]) % 2
                    if val != grid[i][j]:
                        consistent = False
                        break
                if not consistent:
                    break

        # Calculate answer
        if consistent:
            degrees_of_freedom = empty_first_row + empty_first_col - 1
            ans = pow(2, degrees_of_freedom, MOD)
        else:
            ans = 0

        print(ans)

solve()
