def compute_grundy(m, k):
    """Compute the Grundy number for a log of length m with minimum part length k"""
    if m < k:
        return 0

    # Check if m can be split
    can_split = False
    for t in range(2, m + 1):
        if m % t == 0:
            part_length = m // t
            if part_length >= k:
                can_split = True
                break

    if not can_split:
        return 0

    # Compute Grundy number
    grundy = 0
    seen = set()
    for t in range(2, m + 1):
        if m % t == 0:
            part_length = m // t
            if part_length >= k:
                seen.add(compute_grundy(part_length, k))

    # Find mex
    mex = 0
    while mex in seen:
        mex += 1

    return mex

def solve():
    n, m, k = map(int, input().split())

    # Compute Grundy number for a single log
    g = compute_grundy(m, k)

    # Total Grundy number for n logs
    total_grundy = n * g

    if total_grundy > 0:
        print("Timur")
    else:
        print("Marsel")

solve()
