import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    # Read distance matrix
    dist = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(n)]
        dist.append(row)

    k = int(next(it))

    # Process each new road
    results = []
    for _ in range(k):
        a = int(next(it)) - 1  # 0-indexed
        b = int(next(it)) - 1
        c = int(next(it))

        # Check all pairs (i, j)
        for i in range(n):
            for j in range(n):
                # Check if new path through road (a, b) is shorter
                new_dist = min(
                    dist[i][a] + c + dist[b][j],
                    dist[i][b] + c + dist[a][j]
                )
                if new_dist < dist[i][j]:
                    dist[i][j] = new_dist

        # Calculate sum of all pairs
        total = 0
        for i in range(n):
            for j in range(i + 1, n):
                total += dist[i][j]

        results.append(str(total))

    sys.stdout.write(" ".join(results))

if __name__ == "__main__":
    solve()
