import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # If n == 3, we can only flip all three elements
    if n == 3:
        if a == [0, 1, 0] or a == [1, 0, 1]:
            print("NO")
        else:
            print("YES")
        return

    # For n > 3, work from the end
    operations = []

    # Start from the end and work backwards
    for i in range(n - 1, 0, -1):
