# Read input
n = int(input())
swaps = []
for _ in range(n):
    a, b = map(int, input().split())
    swaps.append((a, b))

# Track which positions have been swapped and what value they have
swapped_positions = set()
value_at_position = {}

# Apply all swaps
for a, b in swaps:
    # Swap values at positions a and b
    if a in value_at_position:
        val_a = value_at_position[a]
    else:
        val_a = a

    if b in value_at_position:
        val_b = value_at_position[b]
    else:
        val_b = b

    value_at_position[a] = val_b
    value_at_position[b] = val_a

    swapped_positions.add(a)
    swapped_positions.add(b)

# Count inversions
inversions = 0

# Count inversions between swapped positions
swapped_list = sorted(value_at_position.items())
for i in range(len(swapped_list)):
    pos_i, val_i = swapped_list[i]
    for j in range(i + 1, len(swapped_list)):
        pos_j, val_j = swapped_list[j]
        if val_i > val_j:
            inversions += 1

# Count inversions between swapped positions and non-swapped positions
for pos, val in swapped_list:
    # Count non-swapped positions to the right (j > pos)
    for j in range(pos + 1, 10**9 + 1):
        if j not in swapped_positions:
            if val > j:
                inversions += 1
            break  # Only one non-swapped position to the right

    # Count non-swapped positions to the left (j < pos)
    for j in range(1, pos):
        if j not in swapped_positions:
            if val > j:
                inversions += 1
            break  # Only one non-swapped position to the left

print(inversions)
