MOD = 1000000007

def solve():
    d, n = map(int, input().split())
    a = list(map(int, input().split()))

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for _ in range(n - 1):
        u, v = map(int, input().split())
        graph[u - 1].append(v - 1)
        graph[v - 1].append(u - 1)

    # DP: dp[u][s] = number of valid sets in subtree rooted at u with sum exactly s
    def dfs(u, parent):
        # Initialize with just the node u itself
        dp = defaultdict(int)
        dp[a[u]] = 1

        for v in graph[u]:
            if v == parent:
                continue
            child_dp = dfs(v, u)

            # Combine dp[u] with child_dp
            new_dp = defaultdict(int)

            # Case 1: Don't include any nodes from the child subtree
            for s, cnt in dp.items():
                new_dp[s] = (new_dp[s] + cnt) % MOD

            # Case 2: Include some valid set from the child subtree
            for s1, cnt1 in dp.items():
                for s2, cnt2 in child_dp.items():
                    if s1 + s2 >= d:
                        new_dp[s1 + s2] = (new_dp[s1 + s2] + cnt1 * cnt2) % MOD

        return dp

    result = 0
    dp_root = dfs(0, -1)
    for s, cnt in dp_root.items():
        if s >= d:
            result = (result + cnt) % MOD

    print(result)

solve()
