import sys

def solve():
    # Read input
    data = sys.stdin.buffer.read().splitlines()
    if not data:
        return

    lines = [line.decode().strip() for line in data]

    # Parse first line
    if not lines:
        return

    first_line = lines[0].split()
    if len(first_line) < 2:
        return

    N = int(first_line[0])
    Q = int(first_line[1])

    # Read N words
    words = []
    for i in range(1, N + 1):
        if i >= len(lines):
            break
        words.append(lines[i].strip())

    # Build prefix map: prefix -> list of words starting with this prefix
    prefix_map = {}
    for word in words:
        for i in range(len(word)):
            prefix = word[:i+1]
            if prefix not in prefix_map:
                prefix_map[prefix] = []
            prefix_map[prefix].append(word)

    # Process Q queries
    for i in range(N + 1, N + Q + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) < 2:
            continue
        prefix = parts[0]
        suffix = parts[1]

        # Get words starting with prefix
        words_with_prefix = prefix_map.get(prefix, [])

        # Count how many of those also end with suffix
        count = 0
        for word in words_with_prefix:
            if word.endswith(suffix):
                count += 1

        print(count)

if __name__ == "__main__":
    solve()
"}

