def find_cycle(graph, n):
    """Find a cycle in the graph."""
    for start in range(1, n + 1):
        visited = set()
        current = start
        path = []

        while current not in visited:
            visited.add(current)
            path.append(current)
            current = graph[current]

        if current in path:
            # Found a cycle
            cycle_start = path.index(current)
            cycle = path[cycle_start:]

            # Check if this cycle is valid
            # Each vertex in the cycle should have exactly one incoming and one outgoing edge
            # within the cycle
            valid = True
            for v in cycle:
                # Check in-degree
                in_count = 0
                for u in cycle:
                    if graph[u] == v:
                        in_count += 1
                if in_count != 1:
                    valid = False
                    break

                # Check out-degree
                out_count = 0
                for u in cycle:
                    if u == v:
                        out_count += 1
                if out_count != 1:
                    valid = False
                    break

            if valid:
                return cycle

    return None

def solve():
    n, m = map(int, input().split())
    graph = {}

    for _ in range(m):
        a, b = map(int, input().split())
        graph[a] = b

    # Find a cycle
    cycle = find_cycle(graph, n)

    if cycle:
        print(len(cycle))
        for v in cycle:
            print(v)
    else:
        print(-1)

solve()
