def find_cycle(graph, n):
    """Find a cycle in the graph."""
    for start in range(1, n + 1):
        if start not in graph:
            continue  # Skip vertices without outgoing edges

        visited = set()
        current = start
        path = []

        while current not in visited:
            visited.add(current)
            path.append(current)

            # Check if current has an outgoing edge
            if current in graph:
                current = graph[current]
            else:
                # No outgoing edge, can't form a cycle
                break

        if current in path:
            # Found a cycle
            cycle_start = path.index(current)
            cycle = path[cycle_start:]

            # Check if this cycle is valid
            # Each vertex in the cycle should have exactly one incoming and one outgoing edge
            # within the cycle
            valid = True
            for v in cycle:
                # Check in-degree
                in_count = 0
                for u in cycle:
                    if u in graph and graph[u] == v:
                        in_count += 1
                if in_count != 1:
                    valid = False
                    break

                # Check out-degree
                out_count = 0
                for u in cycle:
                    if u == v:
                        out_count += 1
                if out_count != 1:
                    valid = False
                    break

            if valid:
                return cycle

    return None

