import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)

    # The root must have more than 4 letters, so at least 5 letters
    # The remaining letters must be covered by suffixes of length 2 or 3
    # We cannot have the same suffix twice in a row

    suffixes = set()

    # Try all possible root lengths (from 5 to n-2, because we need at least 2 letters for a suffix)
    for root_len in range(5, n - 1):
        # The remaining letters after the root
        remaining = n - root_len

        # We need to cover 'remaining' letters with suffixes of length 2 or 3
        # We can't have the same suffix twice in a row

        # Try all possible suffix sequences that sum to 'remaining'
        # This is a dynamic programming problem

        # dp[i] = set of suffixes that can end a sequence covering i letters
        dp = [set() for _ in range(remaining + 1)]
        dp[0] = set()

        for i in range(1, remaining + 1):
            # Try adding a suffix of length 2
            if i >= 2:
                suffix = s[root_len:root_len+2]
                if i - 2 >= 0:
                    dp[i] = dp[i] | dp[i-2] | {suffix}

            # Try adding a suffix of length 3
            if i >= 3:
                suffix = s[root_len:root_len+3]
                if i - 3 >= 0:
                    dp[i] = dp[i] | dp[i-3] | {suffix}

        # If we can cover all remaining letters, add the suffixes
        if dp[remaining]:
            suffixes.update(dp[remaining])

    # Sort the suffixes lexicographically
    suffixes = sorted(suffixes)

    # Print the result
    print(len(suffixes))
    for suffix in suffixes:
        print(suffix)

if __name__ == "__main__":
    solve()
"}

