        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1
        m = int(data[idx]); idx += 1

        # Check if all letters appear exactly once
        if a == 1 and b == 1 and c == 1:
            if m == 0:
                results.append("YES")
            else:
                results.append("NO")
