            total = a + b + c
            max_freq = max(a, b, c)
            min_adjacent = max(0, total - max_freq - 1)
            max_adjacent = total - 1

            if min_adjacent <= m <= max_adjacent:
                results.append("YES")
            else:
                results.append("NO")

    sys.stdout.write("\n".join(results))

