MOD = 10**9 + 7
MAX = 10**5 + 1

# Precompute factorials and inverse factorials
fact = [1] * (MAX)
invc = [1] * (MAX)
for i in range(1, MAX):
    fact[i] = fact[i-1] * i % MOD
    invc[i] = pow(fact[i], MOD-2, MOD)

# Precompute Möbius function
mu = [1] * (MAX)
min_prime = [0] * (MAX)
for i in range(2, MAX):
    if min_prime[i] == 0:
        min_prime[i] = i
        for j in range(i*i, MAX, i):
            if min_prime[j] == 0:
                min_prime[j] = i

for i in range(2, MAX):
    if min_prime[i] == i:
        # i is prime
        mu[i] = -1
    else:
        # i has a prime factor
        p = min_prime[i]
        if i // p % p == 0:
            # i has p^2 as a factor
            mu[i] = 0
        else:
            # i has p but not p^2
            mu[i] = mu[i // p]

# Function to compute combination C(n, k)
def comb(n, k):
    if n < 0 or k < 0 or k > n:
        return 0
    return fact[n] * invc[k] % MOD * invc[n - k] % MOD

q = int(input())
for _ in range(q):
    n, f = map(int, input().split())
    if f > n or f < 1:
        print(0)
    else:
        ans = 0
        # Find all divisors of n
        divisors = set()
        for d in range(1, int(n**0.5) + 1):
            if n % d == 0:
                divisors.add(d)
                divisors.add(n // d)
        # Apply Möbius inversion
        for d in divisors:
            if d > n:
                continue
            c = comb(n // d - 1, f - 1)
            ans = (ans + mu[d] * c) % MOD
        print(ans)
