import math

t = int(input())
for _ in range(t):
    x, y, p, q = map(int, input().split())

    # We need to find the smallest k such that:
    # (x + a) = k * p
    # (y + a + b) = k * q
    # a = k * p - x
    # b = k * q - y - a = k * (q-p) + x - y
    # a ≥ 0, b ≥ 0
    # k * p - x ≥ 0 → k ≥ ceil(x/p)
    # k * (q-p) + x - y ≥ 0 → k ≥ ceil((y - x) / (q-p)) if q > p
    # k * q ≥ y

    if p == 0:
        # Need all submissions to be unsuccessful
        # x' = 0, so we need to add (y' - y) unsuccessful submissions
        # Minimum is to add 0 if x = 0 already
        if x == 0:
            print(0)
        else:
            print(-1)
    elif p == q:
        # Need all submissions to be successful
        # x' = y', so we need to add (y' - y) successful submissions
        # Minimum is to add 0 if x = y already
        if x == y:
            print(0)
        else:
            print(-1)
    else:
        # Find minimum k
        k1 = (x + p - 1) // p  # ceil(x/p)

        if q > p:
            k2 = (y - x + q - p - 1) // (q - p)  # ceil((y-x)/(q-p))
        else:
            k2 = 0

        k = max(k1, k2)

        # Check if k * q >= y
        if k * q < y:
            print(-1)
        else:
            # Check if we can achieve with k submissions
            a = k * p - x
            b = k * (q - p) + x - y

            if a >= 0 and b >= 0:
                print(k * q - y)
            else:
                print(-1)
