def is_k_beautiful(x, k):
    digits = set(str(x))
    return len(digits) <= k

def solve_k_1(n):
    s = str(n)
    # Check if n itself is k-beautiful
    if is_k_beautiful(n, 1):
        return n

    # Try all digits from 1 to 9
    for d in range(1, 10):
        candidate = int(str(d) * len(s))
        if candidate >= n:
            return candidate

    # If none found, try increasing the length
    for d in range(1, 10):
        candidate = int(str(d) * (len(s) + 1))
        return candidate

def generate_k_2_candidate(n, d1, d2):
    s = str(n)
    digits = set(str(n))

    # If n already uses both digits, we need to find the next valid number
    if len(digits) == 2:
        # Try to find the next number by incrementing
        # We need to find the smallest number ≥ n that uses only d1 and d2
        # This is complex, let's try a different approach

        # Try to increment from n
        for i in range(n, n + 100000):
            if is_k_beautiful(i, 2) and set(str(i)) <= {d1, d2}:
                return i

    # If n uses only one digit or no digits, we can just use the digits
    if len(digits) == 1:
        # Use the existing digit and add the other digit if needed
        if d1 == digits.pop():
            return int(str(d1) * len(s))
        else:
            return int(str(d2) * len(s))

    # If n uses no digits (shouldn't happen)
    return int(str(d1) * len(s))

def solve_k_2(n):
    s = str(n)
    # Check if n itself is k-beautiful
    if is_k_beautiful(n, 2):
        return n

    # Try all combinations of 2 digits
    for d1 in range(10):
        for d2 in range(10):
            if d1 == d2:
                continue
            candidate = generate_k_2_candidate(n, d1, d2)
            if candidate is not None:
                return candidate

    # If none found, try increasing the length
    for d1 in range(1, 10):
        for d2 in range(10):
            if d1 == d2:
                continue
            candidate = generate_k_2_candidate(n, d1, d2)
            if candidate is not None:
                return candidate

def solve(n, k):
    if k == 1:
        return solve_k_1(n)
    else:
        return solve_k_2(n)

t = int(input())
for _ in range(t):
    n, k = map(int, input().split())
    print(solve(n, k))
